import{_ as a,o as e,c as r,a3 as i}from"./chunks/framework.BlfGB29P.js";const u=JSON.parse('{"title":"架构与实战总览","description":"说明如何把模型、Agent、RAG、工作流和应用基础设施组织为可交付、可演进的完整系统。","frontmatter":{"title":"架构与实战总览","description":"说明如何把模型、Agent、RAG、工作流和应用基础设施组织为可交付、可演进的完整系统。"},"headers":[],"relativePath":"py-agent/architecture/index.md","filePath":"py-agent/architecture/index.md","lastUpdated":1786083160000}'),d={name:"py-agent/architecture/index.md"};function l(o,t,h,n,c,p){return e(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="架构与实战总览" tabindex="-1">架构与实战总览 <a class="header-anchor" href="#架构与实战总览" aria-label="Permalink to &quot;架构与实战总览&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>前面的模块分别讲解 Python 与模型、Agent、RAG、工作流、应用工程和生产能力。本模块回答更高一层的问题：面对一个真实业务目标，怎样确定系统边界、分配组件责任、选择控制结构和技术方案，并用项目与交付证据证明整套系统值得上线。</p><p>这里不会再按某个框架 API 从头实现功能，也不会把架构写成云产品清单。学习主线是“为什么这样设计、有哪些候选、代价是什么、怎样验证选择”。</p><h2 id="_1-模块作用" tabindex="-1">1. 模块作用 <a class="header-anchor" href="#_1-模块作用" aria-label="Permalink to &quot;1. 模块作用&quot;">​</a></h2><p>Agent 系统的难点通常不在单次模型调用，而在多个局部正确的能力能否组成一个整体：</p><ul><li>用户任务是否被转成可验证的架构驱动因素；</li><li>业务规则、模型决策、工作流和人工控制是否各有边界；</li><li>业务数据、执行状态、索引和缓存是否拥有清楚的权威关系；</li><li>模型、框架、租户和外部系统的选择是否符合真实约束；</li><li>某类领域 Agent 是否具备适合自己的观察、动作、状态和成功证据；</li><li>项目是否从需求、实现、测试一直走到部署和验收；</li><li>系统上线后能否基于证据迭代、迁移并最终安全下线。</li></ul><p>本模块把这些问题连接成一条系统设计与交付链，而不是再增加一个孤立的技术专题。</p><h2 id="_2-学习目标" tabindex="-1">2. 学习目标 <a class="header-anchor" href="#_2-学习目标" aria-label="Permalink to &quot;2. 学习目标&quot;">​</a></h2><p>完成本模块后，你应该能够：</p><ol><li>从业务目标、功能需求、约束和质量属性中识别架构驱动因素；</li><li>使用系统上下文、容器、组件、数据和部署视图表达不同层级的设计；</li><li>比较普通函数、Workflow、单 Agent、Agentic Workflow 和多 Agent；</li><li>为业务数据、任务、Checkpoint、记忆、索引、缓存和 Trace 选择存储拓扑；</li><li>设计贯穿请求、状态、检索、工具和运营链路的租户隔离；</li><li>为同步 API、异步消息、Webhook、回调和文件接入选择集成模式；</li><li>根据任务与风险选择模型、框架、交互方式和人工介入点；</li><li>分析浏览器、代码、研究、多模态、数据和实时语音 Agent 的领域架构；</li><li>组织项目范围、技术方案、生产验收和生命周期决策；</li><li>使用 ADR、评测、Trace、故障实验和验收证据复查架构选择。</li></ol><h2 id="_3-知识地图" tabindex="-1">3. 知识地图 <a class="header-anchor" href="#_3-知识地图" aria-label="Permalink to &quot;3. 知识地图&quot;">​</a></h2><table tabindex="0"><thead><tr><th>分组</th><th>核心问题</th><th>主要产物</th></tr></thead><tbody><tr><td><a href="/py-agent/architecture/system-architecture/">系统架构设计</a></td><td>系统受什么约束，边界、控制、数据和集成怎样组织</td><td>架构驱动因素、系统视图、数据与隔离决策</td></tr><tr><td><a href="/py-agent/architecture/technology-product-design/">技术决策与产品设计</a></td><td>模型、框架、交互和人工控制怎样取舍</td><td>选型记录、产品状态、信任控制</td></tr><tr><td><a href="/py-agent/architecture/domain-agent-architectures/">领域 Agent 架构</a></td><td>不同任务环境需要怎样的观察、动作、状态和验证</td><td>领域参考架构与风险清单</td></tr><tr><td><a href="/py-agent/architecture/projects/">项目实战</a></td><td>怎样把专题知识组合成可运行、可测试的完整项目</td><td>代码、数据、测试、部署与验收结果</td></tr><tr><td><a href="/py-agent/architecture/delivery-evolution/">交付与演进</a></td><td>怎样定义完成、批准上线并管理后续变化</td><td>范围契约、技术方案、发布证据与退役计划</td></tr></tbody></table><p>五个分组分别负责架构输入、关键选择、领域差异、完整实现和交付治理。它们不是五套互不相关的知识。</p><h2 id="_4-推荐路径" tabindex="-1">4. 推荐路径 <a class="header-anchor" href="#_4-推荐路径" aria-label="Permalink to &quot;4. 推荐路径&quot;">​</a></h2><h3 id="_4-1-建立系统骨架" tabindex="-1">4.1 建立系统骨架 <a class="header-anchor" href="#_4-1-建立系统骨架" aria-label="Permalink to &quot;4.1 建立系统骨架&quot;">​</a></h3><p>先学习“系统架构设计”，用同一个业务场景依次形成需求卡、系统边界、控制结构、存储拓扑、租户边界和外部集成。此时先不追求所有实现细节，而要让每个组件存在的理由可解释。</p><h3 id="_4-2-完成关键选择" tabindex="-1">4.2 完成关键选择 <a class="header-anchor" href="#_4-2-完成关键选择" aria-label="Permalink to &quot;4.2 完成关键选择&quot;">​</a></h3><p>再进入“技术决策与产品设计”，为模型与框架建立候选比较，并把用户交互、确认、人工审批和信任校准放回系统流程。选型结论必须连接到前一步的约束和质量属性。</p><h3 id="_4-3-按任务选择领域架构" tabindex="-1">4.3 按任务选择领域架构 <a class="header-anchor" href="#_4-3-按任务选择领域架构" aria-label="Permalink to &quot;4.3 按任务选择领域架构&quot;">​</a></h3><p>“领域 Agent 架构”不要求六篇按顺序全部学习。选择与你的任务最接近的一篇，观察领域差异怎样改变 Context、Tool、State、安全和成功 Oracle；需要跨模态或跨领域时再组合参考架构。</p><h3 id="_4-4-用项目和交付闭环验证" tabindex="-1">4.4 用项目和交付闭环验证 <a class="header-anchor" href="#_4-4-用项目和交付闭环验证" aria-label="Permalink to &quot;4.4 用项目和交付闭环验证&quot;">​</a></h3><p>“项目实战”负责完整实现，“交付与演进”负责范围、方案、上线和生命周期。建议至少完成一个项目，并把文章中的示例阈值替换成自己的评测、性能和风险数据。</p><h2 id="_5-与其他模块的边界" tabindex="-1">5. 与其他模块的边界 <a class="header-anchor" href="#_5-与其他模块的边界" aria-label="Permalink to &quot;5. 与其他模块的边界&quot;">​</a></h2><table tabindex="0"><thead><tr><th>相邻模块</th><th>它负责什么</th><th>本模块怎样使用</th></tr></thead><tbody><tr><td>基础与模型</td><td>Python、模型原理和模型调用</td><td>把已有语言与模型能力作为候选组件</td></tr><tr><td>Agent 开发</td><td>LangChain Agent、工具、State、Middleware</td><td>决定 Agent 在系统中的自治和权限边界</td></tr><tr><td>RAG 与记忆</td><td>数据处理、检索、生成和记忆机制</td><td>决定知识与记忆在具体系统中的责任和拓扑</td></tr><tr><td>工作流与多 Agent</td><td>LangGraph、持久执行和协作模式</td><td>选择并组合控制结构，不重复框架 API</td></tr><tr><td>Agent 应用工程</td><td>FastAPI、PostgreSQL、Redis、队列和应用实现</td><td>把架构边界落实为服务与数据基础设施</td></tr><tr><td>质量与生产</td><td>测试、评测、安全、观测和部署机制</td><td>使用这些机制形成架构证据和发布门禁</td></tr></tbody></table><p>本模块不是 Python、数据库、分布式系统或云平台百科。需要机制和实现时回到对应专题；本模块关心这些能力为什么出现、由谁拥有、怎样组合以及如何验收。</p><h2 id="_6-前置知识" tabindex="-1">6. 前置知识 <a class="header-anchor" href="#_6-前置知识" aria-label="Permalink to &quot;6. 前置知识&quot;">​</a></h2><p>开始前应能够：</p><ul><li>阅读 Python 类型和异步代码，理解 API、数据库事务和后台任务的基本作用；</li><li>解释模型消息、结构化输出、工具调用和 Agent 执行循环；</li><li>区分 RAG、短期状态、长期记忆和业务数据；</li><li>理解 Workflow 的 State、Checkpoint、Interrupt、重试和幂等；</li><li>知道测试、评测、Trace、SLO 和发布回滚分别解决什么问题。</li></ul><p>不要求先成为每项技术的专家。遇到实现细节时，应通过文中链接回到对应模块补齐，而不是在架构文章中临时学习一整套 API。</p><h2 id="_7-学习方法与最终产出" tabindex="-1">7. 学习方法与最终产出 <a class="header-anchor" href="#_7-学习方法与最终产出" aria-label="Permalink to &quot;7. 学习方法与最终产出&quot;">​</a></h2><p>阅读每篇文章时持续追问五个问题：</p><ol><li>当前设计要满足哪个用户任务或质量属性；</li><li>哪个组件或系统拥有这个事实与决定；</li><li>正常路径和失败路径分别怎样流动；</li><li>采用更简单或更复杂方案会失去什么；</li><li>哪项测试、评测或运行证据能够证明选择成立。</li></ol><p>完成模块后，至少应能产出一份填写完成的需求与质量属性卡、一组系统和数据视图、若干关键 ADR、一条包含失败与恢复的运行流程，以及一份有真实证据的发布验收记录。架构图本身不是最终结果；能够指导实现、验证和演进的决策才是。</p>',34)])])}const _=a(d,[["render",l]]);export{u as __pageData,_ as default};
